// Fonction helper pour récupérer les traductions
export const getSocialText = (language, path) => {
  const keys = path.split('.');
  let value = socialTranslations[language] || socialTranslations['fr'];
  
  for (const key of keys) {
    value = value?.[key];
    if (value === undefined) {
      // Fallback to French if translation missing
      value = socialTranslations['fr'];
      for (const k of keys) {
        value = value?.[k];
      }
      break;
    }
  }
  
  return value || path;
};
